function stripCodeFences(s) {
  return String(s || '')
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}

function toNumber(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

const webhookBody = $('Webhook').first().json.body;

const rawText =
  $json?.content?.parts?.[0]?.text ??
  $json?.text ??
  '';

const cleaned = stripCodeFences(rawText);

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = { items: [] };
}

let items = Array.isArray(parsed.items) ? parsed.items : [];

items = items
  .map((item) => ({
    width_mm: toNumber(item.width_mm),
    height_mm: toNumber(item.height_mm),
    type: String(item.type || 'glass_panel'),
    glassType: String(item.glassType || 'clear'),
    thickness: toNumber(item.thickness) ?? (String(item.type || '').toLowerCase().includes('door') || String(item.type || '').toLowerCase().includes('shower') ? 10 : 6),
    frameColor: String(item.frameColor || 'Silver'),
  }))
  .filter((i) => i.width_mm && i.height_mm);

const lines = items.map((item, idx) => {
  return [
    `Item ${idx + 1}: ${String(item.type).toUpperCase()}`,
    `Size: ${item.width_mm}mm x ${item.height_mm}mm`,
    `Glass: ${item.glassType} (${item.thickness}mm)`,
    `Frame: ${item.frameColor}`,
  ].join('\n');
});

const confirmationText =
  items.length === 0
    ? `I couldn't read clear measurements from your image.\n\nPlease reply "REDO IMAGE" and send a clearer photo (flat, good light, close enough to read).\n`
    : `Please confirm your glass details:\n\n${lines.join('\n\n')}\n\nReply "YES" to proceed or "REDO IMAGE" to send a new photo.`;

return [
  {
    json: {
      chat_id: webhookBody.chat_id,
      items,
      itemsString: JSON.stringify(items),
      confirmationText,
    },
  },
];
